// These three scenes are original fiction, including each interruption and prop detail.
const COMIC_SETUPS={
 meeting_terms:[b('organizer',S.meeting_terms[0],'phone',{camera:'speaker'}),b('player','Kal matlab kal?','shrug',{camera:'reaction',lookAt:'organizer'}),b('organizer',S.meeting_terms[1],'point',{camera:'speaker'})],
 rumor_wave:[b('nikhil',S.rumor_wave[0],'phone',{camera:'speaker'}),b('player','Tujhe bhi utha liya?','shrug',{camera:'reaction',lookAt:'nikhil'}),b('nikhil',S.rumor_wave[1],'point',{camera:'speaker'})],
 aftermath_account:[b('journalist',S.aftermath_account[0],'phone',{camera:'speaker'}),b('player','Mere pocket se? Main toh saans bhi dheere le raha hoon.','shrug',{camera:'reaction',lookAt:'journalist'}),b('journalist',S.aftermath_account[1],'phone',{camera:'speaker'})]
};
export function stageDayEncounters(encounters){for(const e of encounters){const s=S[e.id];if(!s)continue;if(!e.staging)e.staging={cast:[e.actorId],originalPerformance:true,setup:COMIC_SETUPS[e.id]||[b(e.actorId,s[0],'rest',{camera:'speaker'}),b(e.actorId,s[1],'shrug',{camera:'reaction'})]};e.choices.forEach((c,i)=>{if(s[2]?.[i])c.label=s[2][i];if(!c.responseBeats)c.responseBeats=[b('player',c.label,'shrug',{camera:'speaker',lookAt:e.actorId}),b(e.actorId,s[3]?.[i]||c.line,'rest',{camera:'reaction'})];});}}

export function normalizeSceneTiming(encounters){for(const e of encounters)for(const beat of [...(e.staging?.setup||[]),...e.choices.flatMap(c=>c.responseBeats||[])])beat.duration=Math.max(beat.duration||0,Math.min(5.5,(beat.line||'').split(/\s+/).length*.22+.65));}
